export interface CollegeOrganisationUnit {
  /** Official name, as the university’s site prints it. Not a translation we invented. */
  name: string;
  specialization: Specialization;
  /** Specific faculty/school page, or the organisation page that lists this unit. https. */
  sourceUrl: string;
  /** Optional ISO date when this unit page was read if different from sources[]. */
  readOn?: string;
}

/** Home student of this destination, or a student arriving from any other country. */
export type CollegeApplicantStatus = 'domestic' | 'international';

/** Set only when the official site uses a different page for that degree level. */
export type CollegeApplyLevel = 'undergraduate' | 'postgraduate' | 'all';

export interface CollegeApplyLine {
  audience: CollegeApplicantStatus;
  level?: CollegeApplyLevel;
  text: string;
  sourceUrl: string;
  readOn?: string;
}

export interface CollegeSource {
  url: string;
  /** What this page is: "About", "Faculties", "Undergraduate admission". */
  label: string;
  /** ISO date that page was read. */
  readOn: string;
  /** Surface this source alongside the relevant profile content. */
  section?: 'admission-tests' | 'admission-planning';
}

export interface College {
  id: string;
  slug: string;
  nameEn: string;
  type: CollegeType;
  /** Primary home region (where the institution physically sits). */
  region: RegionSlug;
  /**
   * Extra regions this unit is ALSO relevant to, beyond `region`. Universities
   * usually sit in one place, so this is rarely needed; when present, the unit
   * also surfaces under every listed region. See `resolveDisplayRegions()`.
   */
  regions?: RegionSlug[];
  country: CollegeCountry;
  /** Campus locality used in the directory and other student-facing locations. */
  city: string;
  /** Official mailing locality when it differs from the campus locality. */
  postalCity?: string;
  state?: string;
  /** Omit when the profile does not cite an institutional founding milestone. */
  established?: number;
  /** Use when the source identifies the founding date as the date of a charter. */
  establishmentLabel?: 'Chartered';
  /**
   * QS, THE, or NIRF only. A band (for example 801–1000) is not a number and
   * stays out of this field. `qsYear` / `theYear` and the tied flags are set
   * only when that edition was read on the publisher’s own page.
   */
  ranking?: {
    nirf?: number;
    qs?: number;
    the?: number;
    qsYear?: number;
    theYear?: number;
    qsTied?: boolean;
    theTied?: boolean;
  };
  admissionExams: string[];
  applicationPlatform?: string;
  programLevels: ProgramLevel[];
  /** Omit when this profile has no verified instruction-language detail. */
  englishTaught?: boolean;
  websiteUrl?: string;
  descriptionEn: string;
  courses: string[];
  /**
   * Day the facts in this profile were read on the university’s own pages.
   * Profiles without it keep the site review date. Never a fee, a rank, or a
   * deadline that was not on those pages.
   */
  lastVerified?: string;
  category?: CollegeCategory;
  /** Official institution type when the directory category is broader. */
  institutionLabel?: 'public polytechnic university';
  system?: CollegeSystem;
  /** Only for institute / liberal-arts / specialist. See taxonomy notes. */
  control?: CollegeControl;
  /**
   * Official academic units. The only input to specializations.
   * Omit the whole array rather than store an empty one.
   */
  organisation?: CollegeOrganisationUnit[];
  /**
   * Derived at the module boundary by deriveSpecializations().
   * Authors do not hand-maintain a second list.
   * Absent on legacy records. Never computed from `courses`.
   */
  specializations?: Specialization[];
  /**
   * One sourced clause when instruction is not "all English" or "not English".
   * Omit rather than reuse descriptionEn.
   */
  instructionNote?: { text: string; sourceUrl: string; readOn?: string };
  /**
   * Undergraduate and postgraduate routes, each one short line, only when
   * the admissions page states them. No dates here.
   */
  applyLines?: CollegeApplyLine[];
  sources?: CollegeSource[];
  /** Same meaning as Guide.contentUpdated / EntranceExam.contentUpdated. */
  contentUpdated?: string;
}

export function withDerived(c: College): College {
  if (!c.organisation?.length) return c;
  return { ...c, specializations: deriveSpecializations(c.organisation) };
}

export function collegeModified(c: Pick<College, 'lastVerified' | 'contentUpdated'>): string | undefined {
  if (c.contentUpdated && c.lastVerified && c.contentUpdated > c.lastVerified) {
    return c.contentUpdated;
  }
  return c.lastVerified;
}

