export const COLLEGES: College[] = [
  ...LEGACY_COLLEGES,
  ...USA_BATCH,
  ...INDIA_BATCH,
  ...AUSTRALIA_NZ_BATCH,
  ...UK_IRELAND_BATCH,
  ...EUROPE_BATCH,
  ...EUROPE_PLACES_BATCH,
  ...EAST_SOUTHEAST_ASIA_BATCH,
  ...CANADA_BATCH,
  ...MIDDLE_EAST_BATCH,
  ...RUSSIA_BATCH,
].map(withDerived);

/** Lookup helpers */
export const COLLEGES_BY_TYPE = (type: CollegeType) =>
  COLLEGES.filter((c) => c.type === type);

export const COLLEGES_BY_COUNTRY = (country: CollegeCountry) =>
  COLLEGES.filter((c) => c.country === country);

export const COLLEGES_BY_REGION = (region: string) =>
  COLLEGES.filter((c) => c.region === region);

export const getCollegeBySlug = (slug: string) =>
  COLLEGES.find((c) => c.slug === slug);
